== V1__sheet.sql
-- A sheet: everything else in the app is kept per sheet. A sheet is created the first time it is loaded.
CREATE TABLE sheet (
    id         VARCHAR(100) PRIMARY KEY,
    created_at TIMESTAMP    NOT NULL
);
== V2__sheet_today.sql
-- Each sheet has its own "today": every date-dependent decision and default date uses it, never the
-- real clock. It starts as the real date when the sheet is created.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CAST(created_at AS DATE);
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
== V3__person.sql
-- People on a sheet, listed in the order they were added (by id). A grade is one of A, B or C.
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
== V4__person_name_unique.sql
-- A person's name is unique on the sheet, compared without regard to case and ignoring surrounding
-- spaces. Names are stored trimmed; name_key is the trimmed, lower-cased name the uniqueness is kept on.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200);
UPDATE person SET name_key = LOWER(name);
ALTER TABLE person ALTER COLUMN name_key SET NOT NULL;
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
== V5__claim.sql
-- A person's claims: an amount of 0.00 or more with up to two decimals, a date and a note (may be
-- empty). Listed newest first (by id, descending).
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(12, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(1000)  NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
CREATE INDEX claim_person ON claim (person_id, id);
== V6__rate.sql
-- The sheet's rate for each grade: a percent of 0.00 or more with two decimals. A grade with no
-- row has no rate. A claim's due is its amount times its person's grade's rate, divided by 100.
CREATE TABLE rate (
    sheet_id VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)    NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    pct      DECIMAL(5, 2) NOT NULL CHECK (pct >= 0),
    PRIMARY KEY (sheet_id, grade)
);
== V7__claim_status.sql
-- A claim's status: DRAFT -> OPEN -> SETTLED, and DRAFT or OPEN -> VOID. Only OPEN and SETTLED
-- claims count toward what a person has claimed and what is due.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (status IN ('DRAFT', 'OPEN', 'SETTLED', 'VOID'));
== V8__claim_number.sql
-- An opened claim takes the sheet's next claim number: 1, 2, ... with no gaps, never reused. The
-- sheet counts the numbers it has given out; a draft has no number and voiding a claim clears it.
ALTER TABLE sheet ADD COLUMN claim_numbers_used INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number INT;
== V9__claim_settled_due.sql
-- Settling a claim fixes what is due on it: the amount times its person's grade's rate at that
-- moment, rounded half up to two decimals. Null while the claim is not settled, or when it was
-- settled while the grade had no rate; such a claim's due stays live.
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(12, 2);
== V10__rate_from_date.sql
-- A rate can carry a from-date: a grade may have several rates, one per from-date, and a rate with
-- no from-date applies from the beginning of time. A claim uses its grade's rate with the latest
-- from-date on or before the claim's date; a claim dated before every such rate has no rate.
-- Each row gets its own id; from_key stands for the from-date (no from-date counting as the
-- earliest date) so a grade has at most one rate per from-date.
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
ALTER TABLE rate ADD COLUMN id BIGINT GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD PRIMARY KEY (id);
ALTER TABLE rate ADD CONSTRAINT rate_grade_from_unique UNIQUE (sheet_id, grade, from_key);
== V11__claim_opened_by.sql
-- Who opened a claim: the signed-in user's name, set when it is opened. Null while a draft, or
-- when it was voided without being opened. The user who opened a claim may not settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(255);
== V12__person_version.sql
-- The version of a person: bumped on each save, so an edit made from an older version is refused.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
== V13__statement.sql
-- A statement binds each of its person's counting (OPEN or SETTLED) claims to the figure it had
-- then: a stated claim shows and totals stated_due (null: n/a) until the person's next statement,
-- which rebinds their counting claims and leaves the rest unbound (stated false, live again).
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(12, 2);

-- The statements taken of a person, in the order they were taken (by id): their due-total then
-- (null: n/a), how many of their claims counted, and the sheet's today when it was taken.
CREATE TABLE statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    due_total DECIMAL(12, 2),
    claims    INT            NOT NULL,
    taken_on  DATE           NOT NULL,
    taken_by  VARCHAR(255)   NOT NULL
);
CREATE INDEX statement_sheet ON statement (sheet_id, person_id, id);
== V14__period.sql
-- The sheet's periods: a name, unique on the sheet without regard to case (name_key is the trimmed,
-- lower-cased name), and a from and to date, both inclusive, from on or before to. No two of a
-- sheet's periods overlap. A claim belongs to the period whose dates contain its date, or to none.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200) NOT NULL,
    name_key  VARCHAR(200) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
CREATE INDEX period_sheet_from ON period (sheet_id, from_date);
== V15__period_closed.sql
-- A period can be closed. Closing fixes its due-total at that moment (closed_total), so later
-- changes to rates do not alter it; null while the period is open. No claim dated inside a
-- closed period can be added, edited, opened, settled or voided.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(12, 2);
== V16__void_keeps_number.sql
-- Only a DRAFT claim can be edited; an OPEN claim is changed by voiding it and adding a new one.
-- A voided claim now keeps the number it was given when opened (still never reused); claims voided
-- before this change had theirs cleared and stay without one.
== V17__person_retired.sql
-- A person can be retired from a date; null while they are not. A person with a date set counts as
-- retired at once, whatever the date. No claim dated after it can be added to them, or edited to it.
ALTER TABLE person ADD COLUMN retired_from DATE;
== V18__person_held.sql
-- Whether the person is on hold: while held, their open claims count in no live total.
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
== V19__setting_role.sql
-- The sheet's settings by key: a setting with no row has no value (the clerk limit: no limit).
CREATE TABLE sheet_setting (
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(100) NOT NULL,
    setting_value VARCHAR(200) NOT NULL,
    PRIMARY KEY (sheet_id, setting_key)
);
-- The role the sheet assigns a user name; a name with no row is a clerk.
CREATE TABLE sheet_role (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward')),
    PRIMARY KEY (sheet_id, user_name)
);
== V20__person_patron.sql
-- The people a person has named as their patrons, each at most once, never the person themselves.
CREATE TABLE person_patron (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id),
    CHECK (person_id <> patron_id)
);
CREATE UNIQUE INDEX person_patron_once ON person_patron (person_id, patron_id);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, person_id, id);
== V21__person_grade_dated.sql
-- A person's grade is dated: each grade a person is given is kept with the date it applies from,
-- the first one (no from-date) from the beginning of time. The grade in force on a date is the one
-- with the latest from-date on or before it. from_key stands for the from-date (no from-date counting
-- as the earliest date) so a person has at most one grade per from-date.
CREATE TABLE person_grade (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT     NOT NULL REFERENCES person (id),
    grade     VARCHAR(1) NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    from_date DATE,
    from_key  DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'))
);
CREATE UNIQUE INDEX person_grade_from_unique ON person_grade (person_id, from_key);
INSERT INTO person_grade (person_id, grade) SELECT id, grade FROM person;
ALTER TABLE person DROP COLUMN grade;
== V22__claim_corrects.sql
-- A claim with a negative amount is a correction: it names, by number, the settled claim of the
-- same person that it corrects. Other claims correct none. The amount's check (0.00 or more) has no
-- name to drop it by, so the amount moves to a new column without it.
ALTER TABLE claim ADD COLUMN corrects INTEGER;
ALTER TABLE claim ADD COLUMN signed_amount DECIMAL(12, 2);
UPDATE claim SET signed_amount = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN signed_amount RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD CONSTRAINT claim_correction_names_claim
    CHECK (amount >= 0 AND corrects IS NULL OR amount < 0 AND corrects IS NOT NULL);
== V23__period_numbering.sql
-- A claim's number is now text: the sheet-wide 1, 2, ... as before, or, while the sheet's
-- period-numbering-from setting is in force, <period name>-<n> within the claim's period, or X-<n>
-- for a claim in no period. A correction names the claim it corrects by that text.
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(220);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(220);
-- How many numbers each per-period sequence of a sheet has given out; 'period:<id>' counts a
-- period's, 'none' those of claims in no period. A sequence with no row has given none.
CREATE TABLE claim_number_sequence (
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet (id),
    sequence_key VARCHAR(100) NOT NULL,
    used         INT          NOT NULL,
    PRIMARY KEY (sheet_id, sequence_key)
);
== V24__claim_pending.sql
-- A clerk's settling of a claim whose due is above the clerk limit leaves it PENDING until a steward
-- approves it (SETTLED) or rejects it (OPEN again). PENDING counts like OPEN. The status's check has
-- no name to drop it by, so the status moves to a new column with the wider check.
ALTER TABLE claim ADD COLUMN claim_status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (claim_status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'));
UPDATE claim SET claim_status = status;
ALTER TABLE claim DROP COLUMN status;
ALTER TABLE claim ALTER COLUMN claim_status RENAME TO status;
== V25__claim_listed.sql
-- Claims are listed newest first by their place in the sheet's list, not by id: a claim moved to
-- another person takes the sheet's next place, so it is listed as that person's newest claim. Each
-- claim already stored keeps its place by id.
ALTER TABLE claim ADD COLUMN listed BIGINT;
UPDATE claim SET listed = id;
ALTER TABLE claim ALTER COLUMN listed SET NOT NULL;
CREATE INDEX claim_sheet_listed ON claim (sheet_id, listed);
== V26__claim_due_by.sql
-- A claim's due-by is fixed when it is added, from the terms of its person's grade in force on its
-- date (a grade's own terms, setting key terms-<grade>, else the sheet's terms); it does not change
-- when the terms or the claim's date change later. Each claim already stored keeps the due-by it
-- showed: its date plus the sheet's terms (14 days when the sheet set none).
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim c SET due_by = DATEADD(DAY,
    COALESCE((SELECT CAST(s.setting_value AS INT) FROM sheet_setting s
              WHERE s.sheet_id = c.sheet_id AND s.setting_key = 'terms'), 14),
    c.claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
== V27__claim_log.sql
-- A claim's status log: one line per status it has had, in order (position 0 the oldest), each with
-- who made the change, the sheet's today then, and the claim's due as worked out at that moment (null
-- when n/a). A claim already stored has no log of its past.
CREATE TABLE claim_log (
    claim_id BIGINT         NOT NULL REFERENCES claim (id),
    position INT            NOT NULL,
    status   VARCHAR(20)    NOT NULL,
    by_user  VARCHAR(200)   NOT NULL,
    on_date  DATE           NOT NULL,
    due      DECIMAL(12, 2),
    PRIMARY KEY (claim_id, position)
);
== V28__person_hold.sql
-- A person's holds are dated: each runs from its from-date to its to-date (none: open-ended), and a
-- person may have several over time. Only their open claims dated within a hold, and not bound by a
-- statement, are left out of the live totals. A person held before this has a hold from the
-- beginning of time (no from-date), open-ended.
CREATE TABLE person_hold (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE,
    to_date   DATE
);
INSERT INTO person_hold (person_id) SELECT id FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
== V29__rate_to_date.sql
-- A rate can carry a to-date: it is in force through that date and no longer. A claim dated after
-- the to-date of the rate that would apply to it (the latest from-date on or before the claim's
-- date) has no rate. A to-date is never before the rate's from-date.
ALTER TABLE rate ADD COLUMN to_date DATE;
ALTER TABLE rate ADD CONSTRAINT rate_to_not_before_from CHECK (to_date IS NULL OR from_date IS NULL OR to_date >= from_date);
== V30__period_person_total.sql
-- Closing a period also fixes, at that moment, each person's due-total for it: the figures of their
-- counting claims dated in it. A person with no row (added after the close) has 0.00 for it.
-- Reopening removes the rows: the figures are live again.
CREATE TABLE period_person_total (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL,
    total     DECIMAL(12, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
== V31__setting_dated.sql
-- The settings that carry a figure (the floor, the late percent, the sheet's and each grade's terms,
-- the clerk limit and the cap) are dated: each value is in force from its from-date until the next
-- from-date of the same key. A blank value clears the setting from its date (no limit, no cap, a
-- grade's own terms falling back to the sheet's). Before every from-date a key has its starting value.
CREATE TABLE sheet_setting_dated (
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(100) NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(200) NOT NULL,
    PRIMARY KEY (sheet_id, setting_key, from_date)
);
-- The values already set stay in force on every date.
INSERT INTO sheet_setting_dated (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, setting_key, DATE '0001-01-01', setting_value FROM sheet_setting
    WHERE setting_key IN ('floor', 'late-pct', 'terms', 'terms-A', 'terms-B', 'terms-C', 'clerk-limit', 'cap');
DELETE FROM sheet_setting
    WHERE setting_key IN ('floor', 'late-pct', 'terms', 'terms-A', 'terms-B', 'terms-C', 'clerk-limit', 'cap');
== V32__claim_deferred.sql
-- An OPEN claim can be deferred to a date after the sheet's today: until the sheet's today reaches
-- that date it counts in no total, is not overdue, cannot be settled and no statement binds it.
-- Null when the claim was never deferred.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
== V33__claim_proofs.sql
-- A claim's proofs count, raised by one at a time while it is not SETTLED or VOID. A claim whose due
-- is above the sheet's proof threshold cannot be settled or approved while it has none.
ALTER TABLE claim ADD COLUMN proofs INTEGER NOT NULL DEFAULT 0;
== V34__role_viewer.sql
-- A viewer is a third role: it sees the sheet and changes nothing. The role check is widened by
-- rebuilding the table, as its check constraint has no name to drop.
CREATE TABLE sheet_role_v (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward', 'viewer')),
    PRIMARY KEY (sheet_id, user_name)
);
INSERT INTO sheet_role_v (sheet_id, user_name, role) SELECT sheet_id, user_name, role FROM sheet_role;
DROP TABLE sheet_role;
ALTER TABLE sheet_role_v RENAME TO sheet_role;
== V35__claim_split_from.sql
-- The number of the claim an OPEN claim was split from; none for a claim that was not split off.
ALTER TABLE claim ADD COLUMN split_from VARCHAR(255);
== V36__person_watch.sql
-- The users watching a person, each at most once; the id keeps the order they started watching.
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    user_name VARCHAR(255) NOT NULL
);
CREATE UNIQUE INDEX person_watch_once ON person_watch (person_id, user_name);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, user_name);
== V37__delegation.sql
-- A steward's delegation of the steward role to a user name for a from-date to a to-date, inclusive;
-- the id keeps the order they were made.
CREATE TABLE delegation (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name    VARCHAR(200) NOT NULL,
    from_date    DATE         NOT NULL,
    to_date      DATE         NOT NULL,
    delegated_by VARCHAR(255) NOT NULL,
    CHECK (to_date >= from_date)
);
CREATE INDEX delegation_sheet ON delegation (sheet_id, user_name);
== V38__sheet_archived.sql
-- A steward may archive a sheet: it stays visible, and every change on it is refused.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
== V39__person_terms.sql
-- A person may have their own terms, in days; none means the terms of their grade, else the sheet's.
ALTER TABLE person ADD COLUMN terms INTEGER;
== V40__claim_locked_by.sql
-- Opening a claim's editor locks the claim for other users until it is saved or cancelled, or the
-- sheet's today changes; none when the claim is not locked.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(255);
== V41__period_soft_close.sql
-- A period can be soft-closed: its due-total (closed_total) and each person's due-total for it
-- (period_person_total) are fixed as a close fixes them, but claims dated inside it can still be
-- added, edited, opened, settled and voided. A soft-closed period is not closed; it can be closed
-- (fixing the figures afresh) or reopened.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN DEFAULT FALSE NOT NULL;
-- A claim added while the period its date falls in was soft-closed is a late entry.
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
== V42__statement_as_of.sql
-- A statement can be taken as of a date on or before the sheet's today: it binds the person's claims
-- as they stood at the end of that date, counting every change made while the sheet's today was on or
-- before it. So each change a figure depends on keeps the sheet's today it was made on (made_on; null:
-- made before this was kept, counting on every date).

-- The statement's date: the date it was taken as of, else the sheet's today when it was taken.
ALTER TABLE statement ADD COLUMN stated_on DATE;
UPDATE statement SET stated_on = taken_on;
ALTER TABLE statement ALTER COLUMN stated_on SET NOT NULL;

-- Each binding of a claim to a figure by a statement, and each loss of one (a later statement leaving it
-- out, its statement cancelled, its moving or splitting), oldest first.
CREATE TABLE claim_binding (
    claim_id   BIGINT  NOT NULL REFERENCES claim (id),
    position   INT     NOT NULL,
    on_date    DATE,
    stated     BOOLEAN NOT NULL,
    stated_due DECIMAL(12, 2),
    PRIMARY KEY (claim_id, position)
);
INSERT INTO claim_binding (claim_id, position, stated, stated_due)
    SELECT id, 0, TRUE, stated_due FROM claim WHERE stated;

-- Each setting of a rate, oldest first: a rate set for a grade and from-date replaces the one before it.
CREATE TABLE rate_change (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    grade     VARCHAR(1)    NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    from_date DATE,
    to_date   DATE,
    pct       DECIMAL(5, 2) NOT NULL,
    made_on   DATE
);
CREATE INDEX rate_change_sheet ON rate_change (sheet_id, id);
INSERT INTO rate_change (sheet_id, grade, from_date, to_date, pct)
    SELECT sheet_id, grade, from_date, to_date, pct FROM rate ORDER BY id;

-- Each recording of a dated setting, oldest first: a value recorded for a key and from-date replaces
-- the one before it.
CREATE TABLE setting_change (
    id            BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(100) NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(200) NOT NULL,
    made_on       DATE
);
CREATE INDEX setting_change_sheet ON setting_change (sheet_id, id);
INSERT INTO setting_change (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, setting_key, from_date, setting_value FROM sheet_setting_dated;

-- When a person was added, given each grade, put on each hold and retired.
ALTER TABLE person ADD COLUMN added_on DATE;
ALTER TABLE person ADD COLUMN retired_made_on DATE;
ALTER TABLE person_grade ADD COLUMN made_on DATE;
ALTER TABLE person_hold ADD COLUMN made_on DATE;
== V43__sheet_history.sql
-- What each sheet held at the end of each of its todays, for the as-of view: after every change
-- the sheet's rows are kept against the today the change was made on (the latest change on that
-- today wins), numbered in the order the changes were made. Not referenced by, nor referencing, the
-- sheet's own tables, so it is never part of what it records.
CREATE SEQUENCE sheet_history_seq;
CREATE TABLE sheet_history (
    sheet_id  VARCHAR(100) NOT NULL,
    today     DATE         NOT NULL,
    seq       BIGINT       NOT NULL,
    rows_data BLOB         NOT NULL,
    PRIMARY KEY (sheet_id, today)
);
CREATE INDEX sheet_history_seq_order ON sheet_history (sheet_id, seq);
== V44__claim_reminded.sql
-- An OPEN or PENDING claim can be reminded, once per sheet's today: the last day a reminder was
-- written for it. Null when it never was.
ALTER TABLE claim ADD COLUMN reminded_on DATE;
== V45__holiday.sql
-- The sheet's holidays, each date at most once. A claim's due-by falling on one, when it is fixed,
-- moves to the next day that is not a holiday; due-by dates already fixed are kept as they are.
CREATE TABLE holiday (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet (id),
    holiday_date DATE         NOT NULL
);
CREATE UNIQUE INDEX holiday_once ON holiday (sheet_id, holiday_date);
== V47__claim_ref.sql
-- A claim may carry an external reference, unique on its sheet without regard to case; null when it has none.
ALTER TABLE claim ADD COLUMN ref VARCHAR(220);
CREATE INDEX claim_ref_key ON claim (sheet_id, ref);
== V48__claim_tags.sql
-- A claim may carry tags: lower-cased, sorted and comma separated; null when it has none.
ALTER TABLE claim ADD COLUMN tags VARCHAR(1000);
-- Every tag ever used on a sheet, each once, kept when no claim carries it any more.
CREATE TABLE sheet_tag (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(220) NOT NULL
);
CREATE UNIQUE INDEX sheet_tag_once ON sheet_tag (sheet_id, name);
== V49__void_reason.sql
-- The sheet's void reasons, each at most once. While a sheet has any, voiding a claim needs one of them.
CREATE TABLE void_reason (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    reason   VARCHAR(100) NOT NULL
);
CREATE UNIQUE INDEX void_reason_once ON void_reason (sheet_id, reason);
-- The reason a claim was voided with; null when it is not void or was voided with none.
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(100);
== V50__claim_comment.sql
-- A claim's comments, in the order they were written (position 0 the oldest), each with who wrote it
-- and the sheet's today then.
CREATE TABLE claim_comment (
    claim_id BIGINT         NOT NULL REFERENCES claim (id),
    position INT            NOT NULL,
    by_user  VARCHAR(200)   NOT NULL,
    on_date  DATE           NOT NULL,
    text     VARCHAR(1000)  NOT NULL,
    PRIMARY KEY (claim_id, position)
);
== V51__claim_edited_by.sql
-- Who last edited a claim (through its form or its row's amount entry): the signed-in user's name,
-- set on each saved edit. Null when it was never edited. Like its opener, the user who last edited a
-- claim may not settle or approve it.
ALTER TABLE claim ADD COLUMN edited_by VARCHAR(255);
== V52__settle_batch.sql
-- Settle batches: a bulk settle that settles (or leaves pending) at least one claim is the sheet's
-- next batch, numbered 1, 2, ... Each claim it settled keeps the batch's number; null for a claim
-- settled one at a time. The sheet counts the batches it has had.
ALTER TABLE sheet ADD COLUMN settle_batches_used INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN settle_batch INT;
== V53__person_contact.sql
-- A person may have a contact, stored trimmed and lower-cased; none is null. A contact is unique on the sheet.
ALTER TABLE person ADD COLUMN contact VARCHAR(200);
CREATE UNIQUE INDEX person_sheet_contact ON person (sheet_id, contact);
== V54__person_alias.sql
-- A person may have aliases. An alias shares the names' uniqueness on the sheet: compared without
-- regard to case and ignoring surrounding spaces, it equals no name and no other alias there. Aliases
-- are stored trimmed; alias_key is the trimmed, lower-cased alias the uniqueness among aliases is kept on.
CREATE TABLE person_alias (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    alias     VARCHAR(200) NOT NULL,
    alias_key VARCHAR(200) NOT NULL
);
CREATE UNIQUE INDEX person_alias_sheet_key ON person_alias (sheet_id, alias_key);
== V55__claim_template.sql
-- The sheet's claim templates: a name (stored trimmed, once per sheet), an amount and a note. Saving
-- a name again replaces its amount and note; a claim made from a template copies them, so it keeps
-- them whatever the template becomes.
CREATE TABLE claim_template (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    amount   DECIMAL(12, 2) NOT NULL,
    note     VARCHAR(1000) NOT NULL
);
CREATE UNIQUE INDEX claim_template_once ON claim_template (sheet_id, name);
== V56__pool.sql
-- The sheet's pools: a name (stored trimmed, once per sheet) and its members, each a person of the
-- sheet with a share percent (more than 0.00, at most 100.00). A person is in a pool at most once, and
-- may be in several pools.
CREATE TABLE pool (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL
);
CREATE UNIQUE INDEX pool_once ON pool (sheet_id, name);

CREATE TABLE pool_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    pool_id   BIGINT        NOT NULL REFERENCES pool (id),
    person_id BIGINT        NOT NULL REFERENCES person (id),
    share     DECIMAL(5, 2) NOT NULL CHECK (share > 0 AND share <= 100)
);
CREATE UNIQUE INDEX pool_member_once ON pool_member (pool_id, person_id);
== V57__sheet_parent.sql
-- A sheet's parent: the sheet whose rates (then its parent's, up to three levels up) are used where the
-- sheet has none in force. Not dated, and not part of the sheet's as-of history: the sheet is keyed by
-- child_id rather than sheet_id, and neither column references sheet, so the as-of view keeps the parent
-- the sheet names now.
CREATE TABLE sheet_parent (
    child_id  VARCHAR(100) PRIMARY KEY,
    parent_id VARCHAR(100) NOT NULL
);
== V58__claim_deleted.sql
-- A DRAFT claim can be deleted: it is DELETED, counts nowhere and can only be restored (a DRAFT again)
-- on the sheet's today it was deleted, as its status log records it. The status's check has no name to
-- drop it by, so the status moves to a new column with the wider check.
ALTE

file.content:
== V1__sheet.sql
-- A sheet: everything else in the app is kept per sheet. A sheet is created the first time it is loaded.
CREATE TABLE sheet (
    id         VARCHAR(100) PRIMARY KEY,
    created_at TIMESTAMP    NOT NULL
);
== V2__sheet_today.sql
-- Each sheet has its own "today": every date-dependent decision and default date uses it, never the
-- real clock. It starts as the real date when the sheet is created.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CAST(created_at AS DATE);
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
== V3__person.sql
-- People on a sheet, listed in the order they were added (by id). A grade is one of A, B or C.
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
== V4__person_name_unique.sql
-- A person's name is unique on the sheet, compared without regard to case and ignoring surrounding
-- spaces. Names are stored trimmed; name_key is the trimmed, lower-cased name the uniqueness is kept on.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200);
UPDATE person SET name_key = LOWER(name);
ALTER TABLE person ALTER COLUMN name_key SET NOT NULL;
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
== V5__claim.sql
-- A person's claims: an amount of 0.00 or more with up to two decimals, a date and a note (may be
-- empty). Listed newest first (by id, descending).
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(12, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(1000)  NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
CREATE INDEX claim_person ON claim (person_id, id);
== V6__rate.sql
-- The sheet's rate for each grade: a percent of 0.00 or more with two decimals. A grade with no
-- row has no rate. A claim's due is its amount times its person's grade's rate, divided by 100.
CREATE TABLE rate (
    sheet_id VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)    NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    pct      DECIMAL(5, 2) NOT NULL CHECK (pct >= 0),
    PRIMARY KEY (sheet_id, grade)
);
== V7__claim_status.sql
-- A claim's status: DRAFT -> OPEN -> SETTLED, and DRAFT or OPEN -> VOID. Only OPEN and SETTLED
-- claims count toward what a person has claimed and what is due.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (status IN ('DRAFT', 'OPEN', 'SETTLED', 'VOID'));
== V8__claim_number.sql
-- An opened claim takes the sheet's next claim number: 1, 2, ... with no gaps, never reused. The
-- sheet counts the numbers it has given out; a draft has no number and voiding a claim clears it.
ALTER TABLE sheet ADD COLUMN claim_numbers_used INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number INT;
== V9__claim_settled_due.sql
-- Settling a claim fixes what is due on it: the amount times its person's grade's rate at that
-- moment, rounded half up to two decimals. Null while the claim is not settled, or when it was
-- settled while the grade had no rate; such a claim's due stays live.
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(12, 2);
== V10__rate_from_date.sql
-- A rate can carry a from-date: a grade may have several rates, one per from-date, and a rate with
-- no from-date applies from the beginning of time. A claim uses its grade's rate with the latest
-- from-date on or before the claim's date; a claim dated before every such rate has no rate.
-- Each row gets its own id; from_key stands for the from-date (no from-date counting as the
-- earliest date) so a grade has at most one rate per from-date.
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
ALTER TABLE rate ADD COLUMN id BIGINT GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD PRIMARY KEY (id);
ALTER TABLE rate ADD CONSTRAINT rate_grade_from_unique UNIQUE (sheet_id, grade, from_key);
== V11__claim_opened_by.sql
-- Who opened a claim: the signed-in user's name, set when it is opened. Null while a draft, or
-- when it was voided without being opened. The user who opened a claim may not settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(255);
== V12__person_version.sql
-- The version of a person: bumped on each save, so an edit made from an older version is refused.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
== V13__statement.sql
-- A statement binds each of its person's counting (OPEN or SETTLED) claims to the figure it had
-- then: a stated claim shows and totals stated_due (null: n/a) until the person's next statement,
-- which rebinds their counting claims and leaves the rest unbound (stated false, live again).
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(12, 2);

-- The statements taken of a person, in the order they were taken (by id): their due-total then
-- (null: n/a), how many of their claims counted, and the sheet's today when it was taken.
CREATE TABLE statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    due_total DECIMAL(12, 2),
    claims    INT            NOT NULL,
    taken_on  DATE           NOT NULL,
    taken_by  VARCHAR(255)   NOT NULL
);
CREATE INDEX statement_sheet ON statement (sheet_id, person_id, id);
== V14__period.sql
-- The sheet's periods: a name, unique on the sheet without regard to case (name_key is the trimmed,
-- lower-cased name), and a from and to date, both inclusive, from on or before to. No two of a
-- sheet's periods overlap. A claim belongs to the period whose dates contain its date, or to none.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200) NOT NULL,
    name_key  VARCHAR(200) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
CREATE INDEX period_sheet_from ON period (sheet_id, from_date);
== V15__period_closed.sql
-- A period can be closed. Closing fixes its due-total at that moment (closed_total), so later
-- changes to rates do not alter it; null while the period is open. No claim dated inside a
-- closed period can be added, edited, opened, settled or voided.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(12, 2);
== V16__void_keeps_number.sql
-- Only a DRAFT claim can be edited; an OPEN claim is changed by voiding it and adding a new one.
-- A voided claim now keeps the number it was given when opened (still never reused); claims voided
-- before this change had theirs cleared and stay without one.
== V17__person_retired.sql
-- A person can be retired from a date; null while they are not. A person with a date set counts as
-- retired at once, whatever the date. No claim dated after it can be added to them, or edited to it.
ALTER TABLE person ADD COLUMN retired_from DATE;
== V18__person_held.sql
-- Whether the person is on hold: while held, their open claims count in no live total.
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
== V19__setting_role.sql
-- The sheet's settings by key: a setting with no row has no value (the clerk limit: no limit).
CREATE TABLE sheet_setting (
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(100) NOT NULL,
    setting_value VARCHAR(200) NOT NULL,
    PRIMARY KEY (sheet_id, setting_key)
);
-- The role the sheet assigns a user name; a name with no row is a clerk.
CREATE TABLE sheet_role (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward')),
    PRIMARY KEY (sheet_id, user_name)
);
== V20__person_patron.sql
-- The people a person has named as their patrons, each at most once, never the person themselves.
CREATE TABLE person_patron (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id),
    CHECK (person_id <> patron_id)
);
CREATE UNIQUE INDEX person_patron_once ON person_patron (person_id, patron_id);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, person_id, id);
== V21__person_grade_dated.sql
-- A person's grade is dated: each grade a person is given is kept with the date it applies from,
-- the first one (no from-date) from the beginning of time. The grade in force on a date is the one
-- with the latest from-date on or before it. from_key stands for the from-date (no from-date counting
-- as the earliest date) so a person has at most one grade per from-date.
CREATE TABLE person_grade (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT     NOT NULL REFERENCES person (id),
    grade     VARCHAR(1) NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    from_date DATE,
    from_key  DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'))
);
CREATE UNIQUE INDEX person_grade_from_unique ON person_grade (person_id, from_key);
INSERT INTO person_grade (person_id, grade) SELECT id, grade FROM person;
ALTER TABLE person DROP COLUMN grade;
== V22__claim_corrects.sql
-- A claim with a negative amount is a correction: it names, by number, the settled claim of the
-- same person that it corrects. Other claims correct none. The amount's check (0.00 or more) has no
-- name to drop it by, so the amount moves to a new column without it.
ALTER TABLE claim ADD COLUMN corrects INTEGER;
ALTER TABLE claim ADD COLUMN signed_amount DECIMAL(12, 2);
UPDATE claim SET signed_amount = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN signed_amount RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD CONSTRAINT claim_correction_names_claim
    CHECK (amount >= 0 AND corrects IS NULL OR amount < 0 AND corrects IS NOT NULL);
== V23__period_numbering.sql
-- A claim's number is now text: the sheet-wide 1, 2, ... as before, or, while the sheet's
-- period-numbering-from setting is in force, <period name>-<n> within the claim's period, or X-<n>
-- for a claim in no period. A correction names the claim it corrects by that text.
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(220);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(220);
-- How many numbers each per-period sequence of a sheet has given out; 'period:<id>' counts a
-- period's, 'none' those of claims in no period. A sequence with no row has given none.
CREATE TABLE claim_number_sequence (
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet (id),
    sequence_key VARCHAR(100) NOT NULL,
    used         INT          NOT NULL,
    PRIMARY KEY (sheet_id, sequence_key)
);
== V24__claim_pending.sql
-- A clerk's settling of a claim whose due is above the clerk limit leaves it PENDING until a steward
-- approves it (SETTLED) or rejects it (OPEN again). PENDING counts like OPEN. The status's check has
-- no name to drop it by, so the status moves to a new column with the wider check.
ALTER TABLE claim ADD COLUMN claim_status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (claim_status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'));
UPDATE claim SET claim_status = status;
ALTER TABLE claim DROP COLUMN status;
ALTER TABLE claim ALTER COLUMN claim_status RENAME TO status;
== V25__claim_listed.sql
-- Claims are listed newest first by their place in the sheet's list, not by id: a claim moved to
-- another person takes the sheet's next place, so it is listed as that person's newest claim. Each
-- claim already stored keeps its place by id.
ALTER TABLE claim ADD COLUMN listed BIGINT;
UPDATE claim SET listed = id;
ALTER TABLE claim ALTER COLUMN listed SET NOT NULL;
CREATE INDEX claim_sheet_listed ON claim (sheet_id, listed);
== V26__claim_due_by.sql
-- A claim's due-by is fixed when it is added, from the terms of its person's grade in force on its
-- date (a grade's own terms, setting key terms-<grade>, else the sheet's terms); it does not change
-- when the terms or the claim's date change later. Each claim already stored keeps the due-by it
-- showed: its date plus the sheet's terms (14 days when the sheet set none).
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim c SET due_by = DATEADD(DAY,
    COALESCE((SELECT CAST(s.setting_value AS INT) FROM sheet_setting s
              WHERE s.sheet_id = c.sheet_id AND s.setting_key = 'terms'), 14),
    c.claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
== V27__claim_log.sql
-- A claim's status log: one line per status it has had, in order (position 0 the oldest), each with
-- who made the change, the sheet's today then, and the claim's due as worked out at that moment (null
-- when n/a). A claim already stored has no log of its past.
CREATE TABLE claim_log (
    claim_id BIGINT         NOT NULL REFERENCES claim (id),
    position INT            NOT NULL,
    status   VARCHAR(20)    NOT NULL,
    by_user  VARCHAR(200)   NOT NULL,
    on_date  DATE           NOT NULL,
    due      DECIMAL(12, 2),
    PRIMARY KEY (claim_id, position)
);
== V28__person_hold.sql
-- A person's holds are dated: each runs from its from-date to its to-date (none: open-ended), and a
-- person may have several over time. Only their open claims dated within a hold, and not bound by a
-- statement, are left out of the live totals. A person held before this has a hold from the
-- beginning of time (no from-date), open-ended.
CREATE TABLE person_hold (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE,
    to_date   DATE
);
INSERT INTO person_hold (person_id) SELECT id FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
== V29__rate_to_date.sql
-- A rate can carry a to-date: it is in force through that date and no longer. A claim dated after
-- the to-date of the rate that would apply to it (the latest from-date on or before the claim's
-- date) has no rate. A to-date is never before the rate's from-date.
ALTER TABLE rate ADD COLUMN to_date DATE;
ALTER TABLE rate ADD CONSTRAINT rate_to_not_before_from CHECK (to_date IS NULL OR from_date IS NULL OR to_date >= from_date);
== V30__period_person_total.sql
-- Closing a period also fixes, at that moment, each person's due-total for it: the figures of their
-- counting claims dated in it. A person with no row (added after the close) has 0.00 for it.
-- Reopening removes the rows: the figures are live again.
CREATE TABLE period_person_total (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL,
    total     DECIMAL(12, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
== V31__setting_dated.sql
-- The settings that carry a figure (the floor, the late percent, the sheet's and each grade's terms,
-- the clerk limit and the cap) are dated: each value is in force from its from-date until the next
-- from-date of the same key. A blank value clears the setting from its date (no limit, no cap, a
-- grade's own terms falling back to the sheet's). Before every from-date a key has its starting value.
CREATE TABLE sheet_setting_dated (
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(100) NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(200) NOT NULL,
    PRIMARY KEY (sheet_id, setting_key, from_date)
);
-- The values already set stay in force on every date.
INSERT INTO sheet_setting_dated (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, setting_key, DATE '0001-01-01', setting_value FROM sheet_setting
    WHERE setting_key IN ('floor', 'late-pct', 'terms', 'terms-A', 'terms-B', 'terms-C', 'clerk-limit', 'cap');
DELETE FROM sheet_setting
    WHERE setting_key IN ('floor', 'late-pct', 'terms', 'terms-A', 'terms-B', 'terms-C', 'clerk-limit', 'cap');
== V32__claim_deferred.sql
-- An OPEN claim can be deferred to a date after the sheet's today: until the sheet's today reaches
-- that date it counts in no total, is not overdue, cannot be settled and no statement binds it.
-- Null when the claim was never deferred.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
== V33__claim_proofs.sql
-- A claim's proofs count, raised by one at a time while it is not SETTLED or VOID. A claim whose due
-- is above the sheet's proof threshold cannot be settled or approved while it has none.
ALTER TABLE claim ADD COLUMN proofs INTEGER NOT NULL DEFAULT 0;
== V34__role_viewer.sql
-- A viewer is a third role: it sees the sheet and changes nothing. The role check is widened by
-- rebuilding the table, as its check constraint has no name to drop.
CREATE TABLE sheet_role_v (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward', 'viewer')),
    PRIMARY KEY (sheet_id, user_name)
);
INSERT INTO sheet_role_v (sheet_id, user_name, role) SELECT sheet_id, user_name, role FROM sheet_role;
DROP TABLE sheet_role;
ALTER TABLE sheet_role_v RENAME TO sheet_role;
== V35__claim_split_from.sql
-- The number of the claim an OPEN claim was split from; none for a claim that was not split off.
ALTER TABLE claim ADD COLUMN split_from VARCHAR(255);
== V36__person_watch.sql
-- The users watching a person, each at most once; the id keeps the order they started watching.
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    user_name VARCHAR(255) NOT NULL
);
CREATE UNIQUE INDEX person_watch_once ON person_watch (person_id, user_name);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, user_name);
== V37__delegation.sql
-- A steward's delegation of the steward role to a user name for a from-date to a to-date, inclusive;
-- the id keeps the order they were made.
CREATE TABLE delegation (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name    VARCHAR(200) NOT NULL,
    from_date    DATE         NOT NULL,
    to_date      DATE         NOT NULL,
    delegated_by VARCHAR(255) NOT NULL,
    CHECK (to_date >= from_date)
);
CREATE INDEX delegation_sheet ON delegation (sheet_id, user_name);
== V38__sheet_archived.sql
-- A steward may archive a sheet: it stays visible, and every change on it is refused.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
== V39__person_terms.sql
-- A person may have their own terms, in days; none means the terms of their grade, else the sheet's.
ALTER TABLE person ADD COLUMN terms INTEGER;
== V40__claim_locked_by.sql
-- Opening a claim's editor locks the claim for other users until it is saved or cancelled, or the
-- sheet's today changes; none when the claim is not locked.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(255);
== V41__period_soft_close.sql
-- A period can be soft-closed: its due-total (closed_total) and each person's due-total for it
-- (period_person_total) are fixed as a close fixes them, but claims dated inside it can still be
-- added, edited, opened, settled and voided. A soft-closed period is not closed; it can be closed
-- (fixing the figures afresh) or reopened.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN DEFAULT FALSE NOT NULL;
-- A claim added while the period its date falls in was soft-closed is a late entry.
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
== V42__statement_as_of.sql
-- A statement can be taken as of a date on or before the sheet's today: it binds the person's claims
-- as they stood at the end of that date, counting every change made while the sheet's today was on or
-- before it. So each change a figure depends on keeps the sheet's today it was made on (made_on; null:
-- made before this was kept, counting on every date).

-- The statement's date: the date it was taken as of, else the sheet's today when it was taken.
ALTER TABLE statement ADD COLUMN stated_on DATE;
UPDATE statement SET stated_on = taken_on;
ALTER TABLE statement ALTER COLUMN stated_on SET NOT NULL;

-- Each binding of a claim to a figure by a statement, and each loss of one (a later statement leaving it
-- out, its statement cancelled, its moving or splitting), oldest first.
CREATE TABLE claim_binding (
    claim_id   BIGINT  NOT NULL REFERENCES claim (id),
    position   INT     NOT NULL,
    on_date    DATE,
    stated     BOOLEAN NOT NULL,
    stated_due DECIMAL(12, 2),
    PRIMARY KEY (claim_id, position)
);
INSERT INTO claim_binding (claim_id, position, stated, stated_due)
    SELECT id, 0, TRUE, stated_due FROM claim WHERE stated;

-- Each setting of a rate, oldest first: a rate set for a grade and from-date replaces the one before it.
CREATE TABLE rate_change (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    grade     VARCHAR(1)    NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    from_date DATE,
    to_date   DATE,
    pct       DECIMAL(5, 2) NOT NULL,
    made_on   DATE
);
CREATE INDEX rate_change_sheet ON rate_change (sheet_id, id);
INSERT INTO rate_change (sheet_id, grade, from_date, to_date, pct)
    SELECT sheet_id, grade, from_date, to_date, pct FROM rate ORDER BY id;

-- Each recording of a dated setting, oldest first: a value recorded for a key and from-date replaces
-- the one before it.
CREATE TABLE setting_change (
    id            BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(100) NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(200) NOT NULL,
    made_on       DATE
);
CREATE INDEX setting_change_sheet ON setting_change (sheet_id, id);
INSERT INTO setting_change (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, setting_key, from_date, setting_value FROM sheet_setting_dated;

-- When a person was added, given each grade, put on each hold and retired.
ALTER TABLE person ADD COLUMN added_on DATE;
ALTER TABLE person ADD COLUMN retired_made_on DATE;
ALTER TABLE person_grade ADD COLUMN made_on DATE;
ALTER TABLE person_hold ADD COLUMN made_on DATE;
== V43__sheet_history.sql
-- What each sheet held at the end of each of its todays, for the as-of view: after every change
-- the sheet's rows are kept against the today the change was made on (the latest change on that
-- today wins), numbered in the order the changes were made. Not referenced by, nor referencing, the
-- sheet's own tables, so it is never part of what it records.
CREATE SEQUENCE sheet_history_seq;
CREATE TABLE sheet_history (
    sheet_id  VARCHAR(100) NOT NULL,
    today     DATE         NOT NULL,
    seq       BIGINT       NOT NULL,
    rows_data BLOB         NOT NULL,
    PRIMARY KEY (sheet_id, today)
);
CREATE INDEX sheet_history_seq_order ON sheet_history (sheet_id, seq);
== V44__claim_reminded.sql
-- An OPEN or PENDING claim can be reminded, once per sheet's today: the last day a reminder was
-- written for it. Null when it never was.
ALTER TABLE claim ADD COLUMN reminded_on DATE;
== V45__holiday.sql
-- The sheet's holidays, each date at most once. A claim's due-by falling on one, when it is fixed,
-- moves to the next day that is not a holiday; due-by dates already fixed are kept as they are.
CREATE TABLE holiday (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet (id),
    holiday_date DATE         NOT NULL
);
CREATE UNIQUE INDEX holiday_once ON holiday (sheet_id, holiday_date);
== V47__claim_ref.sql
-- A claim may carry an external reference, unique on its sheet without regard to case; null when it has none.
ALTER TABLE claim ADD COLUMN ref VARCHAR(220);
CREATE INDEX claim_ref_key ON claim (sheet_id, ref);
== V48__claim_tags.sql
-- A claim may carry tags: lower-cased, sorted and comma separated; null when it has none.
ALTER TABLE claim ADD COLUMN tags VARCHAR(1000);
-- Every tag ever used on a sheet, each once, kept when no claim carries it any more.
CREATE TABLE sheet_tag (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(220) NOT NULL
);
CREATE UNIQUE INDEX sheet_tag_once ON sheet_tag (sheet_id, name);
== V49__void_reason.sql
-- The sheet's void reasons, each at most once. While a sheet has any, voiding a claim needs one of them.
CREATE TABLE void_reason (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    reason   VARCHAR(100) NOT NULL
);
CREATE UNIQUE INDEX void_reason_once ON void_reason (sheet_id, reason);
-- The reason a claim was voided with; null when it is not void or was voided with none.
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(100);
== V50__claim_comment.sql
-- A claim's comments, in the order they were written (position 0 the oldest), each with who wrote it
-- and the sheet's today then.
CREATE TABLE claim_comment (
    claim_id BIGINT         NOT NULL REFERENCES claim (id),
    position INT            NOT NULL,
    by_user  VARCHAR(200)   NOT NULL,
    on_date  DATE           NOT NULL,
    text     VARCHAR(1000)  NOT NULL,
    PRIMARY KEY (claim_id, position)
);
== V51__claim_edited_by.sql
-- Who last edited a claim (through its form or its row's amount entry): the signed-in user's name,
-- set on each saved edit. Null when it was never edited. Like its opener, the user who last edited a
-- claim may not settle or approve it.
ALTER TABLE claim ADD COLUMN edited_by VARCHAR(255);
== V52__settle_batch.sql
-- Settle batches: a bulk settle that settles (or leaves pending) at least one claim is the sheet's
-- next batch, numbered 1, 2, ... Each claim it settled keeps the batch's number; null for a claim
-- settled one at a time. The sheet counts the batches it has had.
ALTER TABLE sheet ADD COLUMN settle_batches_used INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN settle_batch INT;
== V53__person_contact.sql
-- A person may have a contact, stored trimmed and lower-cased; none is null. A contact is unique on the sheet.
ALTER TABLE person ADD COLUMN contact VARCHAR(200);
CREATE UNIQUE INDEX person_sheet_contact ON person (sheet_id, contact);
== V54__person_alias.sql
-- A person may have aliases. An alias shares the names' uniqueness on the sheet: compared without
-- regard to case and ignoring surrounding spaces, it equals no name and no other alias there. Aliases
-- are stored trimmed; alias_key is the trimmed, lower-cased alias the uniqueness among aliases is kept on.
CREATE TABLE person_alias (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    alias     VARCHAR(200) NOT NULL,
    alias_key VARCHAR(200) NOT NULL
);
CREATE UNIQUE INDEX person_alias_sheet_key ON person_alias (sheet_id, alias_key);
== V55__claim_template.sql
-- The sheet's claim templates: a name (stored trimmed, once per sheet), an amount and a note. Saving
-- a name again replaces its amount and note; a claim made from a template copies them, so it keeps
-- them whatever the template becomes.
CREATE TABLE claim_template (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    amount   DECIMAL(12, 2) NOT NULL,
    note     VARCHAR(1000) NOT NULL
);
CREATE UNIQUE INDEX claim_template_once ON claim_template (sheet_id, name);
== V56__pool.sql
-- The sheet's pools: a name (stored trimmed, once per sheet) and its members, each a person of the
-- sheet with a share percent (more than 0.00, at most 100.00). A person is in a pool at most once, and
-- may be in several pools.
CREATE TABLE pool (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL
);
CREATE UNIQUE INDEX pool_once ON pool (sheet_id, name);

CREATE TABLE pool_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    pool_id   BIGINT        NOT NULL REFERENCES pool (id),
    person_id BIGINT        NOT NULL REFERENCES person (id),
    share     DECIMAL(5, 2) NOT NULL CHECK (share > 0 AND share <= 100)
);
CREATE UNIQUE INDEX pool_member_once ON pool_member (pool_id, person_id);
== V57__sheet_parent.sql
-- A sheet's parent: the sheet whose rates (then its parent's, up to three levels up) are used where the
-- sheet has none in force. Not dated, and not part of the sheet's as-of history: the sheet is keyed by
-- child_id rather than sheet_id, and neither column references sheet, so the as-of view keeps the parent
-- the sheet names now.
CREATE TABLE sheet_parent (
    child_id  VARCHAR(100) PRIMARY KEY,
    parent_id VARCHAR(100) NOT NULL
);
== V58__claim_deleted.sql
-- A DRAFT claim can be deleted: it is DELETED, counts nowhere and can only be restored (a DRAFT again)
-- on the sheet's today it was deleted, as its status log records it. The status's check has no name to
-- drop it by, so the status moves to a new column with the wider check.
ALTER TABLE claim ADD COLUMN claim_status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (claim_status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'DELETED'));
UPDATE claim SET claim_status = status;
ALTER TABLE claim DROP COLUMN status;
ALTER TABLE claim ALTER COLUMN claim_status RENAME TO status;
== V59__pool_member_pool.sql
-- A pool member may be another pool of the sheet instead of a person: exactly one of person_id and
-- member_pool_id is set. A pool is a member of at most one pool.
ALTER TABLE pool_member ALTER COLUMN person_id SET NULL;
ALTER TABLE pool_member ADD COLUMN member_pool_id BIGINT REFERENCES pool (id);
ALTER TABLE pool_member ADD CONSTRAINT pool_member_one_kind
    CHECK ((person_id IS NULL) <> (member_pool_id IS NULL));
CREATE UNIQUE INDEX pool_member_pool_once ON pool_member (member_pool_id);
== V60__person_position.sql
-- A person's place in the list, lowest first. A person added carries none until they are moved, and
-- takes their id's place, which is after everyone added before them; a move swaps two people's places.
ALTER TABLE person ADD COLUMN position BIGINT;
UPDATE person SET position = id;
== V61__person_origin.sql
-- The sheet a person was transferred from; null for a person added on their sheet.
ALTER TABLE person ADD COLUMN origin_sheet_id VARCHAR(100);
== V62__pool_member_dated.sql
-- A pool membership may carry a from-date and a to-date (either may be absent: from the beginning of
-- time, or without end). A member whose dates do not include the sheet's today is left out of the pool.
ALTER TABLE pool_member ADD COLUMN from_date DATE;
ALTER TABLE pool_member ADD COLUMN to_date DATE;
ALTER TABLE pool_member ADD CONSTRAINT pool_member_dates
    CHECK (from_date IS NULL OR to_date IS NULL OR to_date >= from_date);
== V63__person_retirement.sql
-- A retired person can be unretired: each past retirement is kept, from its from-date to the sheet's
-- today it was ended on. A claim dated after the from-date and before the to-date stays refused.
CREATE TABLE person_retirement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE   NOT NULL,
    to_date   DATE   NOT NULL,
    made_on   DATE
);
CREATE INDEX person_retirement_person ON person_retirement (person_id);
# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}

# A refusal's reason goes back in the error body's message, so a screen can show why it was refused.
server.error.include-message=always
