package net.officefloor.hq.app.claim;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

/** A claim made by a person on a sheet. */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    /** The date the claim is due by: the {@link #terms}-th business day after {@link #dueFrom}, past
     *  the sheet's holidays; a holiday added on or before it works it out again from the claim's date,
     *  unless the claim is SETTLED or VOID. */
    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    /** The date the claim's due-by counts from: its date when it was added; a later change to the
     *  claim's date leaves it as it is. */
    @Column(name = "due_from", nullable = false)
    private LocalDate dueFrom;

    /** The terms, in business days, the claim was fixed with when it was added, from those of its
     *  person (else their grade's, else the sheet's) in force on its date; later changes to the terms
     *  leave them as they are. */
    @Column(name = "terms", nullable = false)
    private int terms;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** The claim's number, given when it is opened and kept once void; none while a draft. It is the
     *  sheet-wide 1, 2, ..., or while period numbering is in force <period name>-<n> or X-<n>. */
    @Column(name = "claim_number")
    private String number;

    /** What was due on the claim when it was settled; none while unsettled, or when no rate applied then. */
    @Column(name = "settled_due", precision = 12, scale = 2)
    private BigDecimal settledDue;

    /** Who opened the claim; none while a draft, or when voided without being opened. */
    @Column(name = "opened_by")
    private String openedBy;

    /** Who last edited the claim through its form or its row's amount entry; none when never edited. */
    @Column(name = "edited_by")
    private String editedBy;

    /** Whether the person's last statement bound the claim to a figure; it then shows stated due. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The figure the last statement bound the claim to; none when unbound, or when it was n/a then. */
    @Column(name = "stated_due", precision = 12, scale = 2)
    private BigDecimal statedDue;

    /** The number of the settled claim of the same person a correction (a negative amount) corrects; none otherwise. */
    @Column(name = "corrects")
    private String corrects;

    /** The claim's place in the sheet's list, which is newest first: the sheet's next place when it is
     *  added, and again when it is moved to another person. */
    @Column(name = "listed", nullable = false)
    private long listed;

    /** The date the claim is deferred until: while the sheet's today is before it an OPEN claim counts
     *  in no total, is not overdue, cannot be settled and no statement binds it; none when never deferred. */
    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    /** How many proofs the claim has had added. */
    @Column(name = "proofs", nullable = false)
    private int proofs;

    /** The number of the claim this one was split off from; none when it was not split off. */
    @Column(name = "split_from")
    private String splitFrom;

    /** The user whose open editor locks the claim for other users; none when it is not locked. */
    @Column(name = "locked_by")
    private String lockedBy;

    /** Whether the claim was added while the period its due-by falls in was soft-closed. */
    @Column(name = "late_entry", nullable = false)
    private boolean lateEntry;

    /** The last day (the sheet's today then) a reminder was written for the claim; none when never reminded. */
    @Column(name = "reminded_on")
    private LocalDate remindedOn;

    /** The claim's external reference, unique on its sheet without regard to case; none when it has none. */
    @Column(name = "ref")
    private String ref;

    /** The claim's tags, lower-cased, sorted and comma separated; none when it has none. */
    @Column(name = "tags")
    private String tags;

    /** The reason the claim was voided with; none when it is not void or was voided with none. */
    @Column(name = "void_reason")
    private String voidReason;

    /** The number of the bulk settle batch that last settled the claim; none when it was settled one at
     *  a time, or never settled. */
    @Column(name = "settle_batch")
    private Integer settleBatch;

    /** The claim's status log, oldest first: a line for each status it has had. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "claim_log", joinColumns = @JoinColumn(name = "claim_id"))
    @OrderColumn(name = "position")
    private List<ClaimLogLine> log = new ArrayList<>();

    /** The claim's binding history, oldest first: a line for each binding to a figure and each loss of one. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "claim_binding", joinColumns = @JoinColumn(name = "claim_id"))
    @OrderColumn(name = "position")
    private List<ClaimBinding> bindings = new ArrayList<>();

    /** The claim's comments, oldest first. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "claim_comment", joinColumns = @JoinColumn(name = "claim_id"))
    @OrderColumn(name = "position")
    private List<ClaimComment> comments = new ArrayList<>();

    protected Claim() {
    }

    /** A claim whose due-by, the date given, is fixed from its date with the terms given. */
    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, String note, String corrects,
            int terms, LocalDate dueBy) {
        this.sheetId = sheetId;
        this.personId = personId;
        set(amount, date, note, corrects);
        this.dueFrom = date;
        this.terms = terms;
        this.dueBy = dueBy;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public long getListed() {
        return listed;
    }

    public void setListed(long listed) {
        this.listed = listed;
    }

    /** Move the claim to another person, as their newest claim at the place given, while the sheet's today
     *  is the date given: it keeps its number and date, and loses any figure a statement bound it to, its
     *  due live again. */
    public void moveTo(Long personId, long listed, LocalDate today) {
        this.personId = personId;
        this.listed = listed;
        unbind(today);
    }

    /** A copy of the claim for a person on another sheet, at the place in its list given: its status,
     *  dates, terms, note, tags, frozen figure, proofs, log and comments, with the number given (null:
     *  none) and the numbers it corrects and was split from as given; no reference, no binding to a
     *  statement's figure, no lock and no settle batch. */
    public Claim copyTo(String otherSheetId, Long otherPersonId, long otherListed, String otherNumber,
            String otherCorrects, String otherSplitFrom) {
        Claim copy = new Claim();
        copy.sheetId = otherSheetId;
        copy.personId = otherPersonId;
        copy.amount = amount;
        copy.date = date;
        copy.dueBy = dueBy;
        copy.dueFrom = dueFrom;
        copy.terms = terms;
        copy.note = note;
        copy.status = status;
        copy.number = otherNumber;
        copy.settledDue = settledDue;
        copy.openedBy = openedBy;
        copy.editedBy = editedBy;
        copy.corrects = otherCorrects;
        copy.listed = otherListed;
        copy.deferredUntil = deferredUntil;
        copy.proofs = proofs;
        copy.splitFrom = otherSplitFrom;
        copy.lateEntry = lateEntry;
        copy.remindedOn = remindedOn;
        copy.tags = tags;
        copy.voidReason = voidReason;
        for (ClaimLogLine line : log) {
            copy.log.add(new ClaimLogLine(line.getStatus(), line.getBy(), line.getOn(), line.getDue()));
        }
        for (ClaimComment comment : comments) {
            copy.comments.add(new ClaimComment(comment.getBy(), comment.getOn(), comment.getText()));
        }
        return copy;
    }

package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.asof.SheetHistory;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.pool.Pool;
import net.officefloor.hq.app.pool.PoolRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.StatementRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** Transfers a person from one sheet to another; a steward's change. */
@Service
public class TransferService {

    private final PersonRepository people;
    private final PersonAliasRepository aliases;
    private final PersonPatronRepository patrons;
    private final PersonWatchRepository watches;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final StatementRepository statements;
    private final PoolRepository pools;
    private final SettingService settings;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final SheetHistory history;
    private final NameTree tree;
    private final Rollup rollup;
    private final Audit audit;

    public TransferService(PersonRepository people, PersonAliasRepository aliases, PersonPatronRepository patrons,
            PersonWatchRepository watches, ClaimRepository claims, ClaimService claimService,
            StatementRepository statements, PoolRepository pools, SettingService settings, SheetService sheets,
            SheetRepository sheetRows, SheetHistory history, NameTree tree, Rollup rollup, Audit audit) {
        this.people = people;
        this.aliases = aliases;
        this.patrons = patrons;
        this.watches = watches;
        this.claims = claims;
        this.claimService = claimService;
        this.statements = statements;
        this.pools = pools;
        this.settings = settings;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.history = history;
        this.tree = tree;
        this.rollup = rollup;
        this.audit = audit;
    }

    /**
     * Transfer a person to another sheet (a sheet never loaded before starts empty). They arrive with every
     * grade they were given (each from its from-date), their terms, contact and aliases, and their claims
     * with their status, dates, notes, tags, frozen figures, logs and comments, listed as they were; each
     * claim that had a number takes the other sheet's next one, in the order the claims were opened (by the
     * sheet's today when each was opened, then by the order they were added); figures a statement bound are
     * lost, statements are not carried and nor are references. The person then leaves this sheet entirely:
     * their patron links (both ways), pool memberships, watches, holds and statements are dropped. Refused
     * unless the user is a steward of this sheet, for a retired person, to this sheet itself, to an archived
     * sheet, and when the person's name, an alias or their contact is already on the other sheet, or their name or
     * an alias on another sheet of its tree.
     */
    @Transactional
    public void transfer(String sheetId, String user, long id, String toSheetId) {
        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can transfer people.");
        }
        if (toSheetId.equals(sheetId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be transferred to their own sheet.");
        }
        Person from = people.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        if (from.isRetired()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be transferred.");
        }
        sheets.load(toSheetId);
        if (sheetRows.isArchived(toSheetId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The other sheet is archived.");
        }
        List<String> names = new ArrayList<>();
        names.add(from.getName());
        names.addAll(from.getAliases());
        Set<String> elsewhere = tree.keysElsewhere(toSheetId, from.getId());
        for (String name : names) {
            String key = Person.keyOf(name);
            if (elsewhere.contains(key)) {
                throw new ResponseStatusException(HttpStatus.CONFLICT,
                        "That name is already in use on a sheet of the other sheet's tree.");
            }
            if (people.existsBySheetIdAndNameKey(toSheetId, key) || aliases.existsBySheetIdAndAliasKey(toSheetId, key)) {
                throw new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on the other sheet.");
            }
        }
        if (from.getContact() != null && people.existsBySheetIdAndContact(toSheetId, from.getContact())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already in use on the other sheet.");
        }
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        Rollup.Snapshot otherBefore = rollup.snapshot(toSheetId);

        Person arrived = people.saveAndFlush(from.copyTo(toSheetId));

        // The claims that had a number take the other sheet's next, in the order they were opened.
        List<Claim> theirs = claims.findForMove(sheetId, from.getId());
        Map<String, String> numbers = new HashMap<>();
        theirs.stream().filter(c -> c.getNumber() != null)
                .sorted(Comparator.comparing(Claim::openedOn, Comparator.nullsFirst(Comparator.naturalOrder()))
                        .thenComparing(Claim::getId))
                .forEach(c -> numbers.put(c.getNumber(), claimService.nextNumber(toSheetId, c)));
        long listed = claims.lastListed(toSheetId);
        for (Claim claim : theirs.stream().sorted(Comparator.comparingLong(Claim::getListed)).toList()) {
            claims.save(claim.copyTo(toSheetId, arrived.getId(), ++listed, numbers.get(claim.getNumber()),
                    claim.getCorrects() == null ? null : numbers.get(claim.getCorrects()),
                    claim.getSplitFrom() == null ? null : numbers.get(claim.getSplitFrom())));
            claimService.useTags(toSheetId, claim.getTags());
        }
        claims.deleteAll(theirs);
        claims.flush();

        patrons.deleteAll(patrons.findByPersonIdOrderByIdAsc(from.getId()));
        patrons.deleteAll(patrons.findByPatronIdOrderByIdAsc(from.getId()));
        patrons.flush();
        for (Pool pool : pools.findBySheetIdOrderByIdAsc(sheetId)) {
            pool.removeMember(from.getId());
        }
        pools.flush();
        statements.deleteBySheetIdAndPersonId(sheetId, from.getId());
        watches.deleteByPersonId(from.getId());
        people.delete(from);
        people.flush();

        audit.recordOnCommit("PERSON_TRANSFERRED sheet=" + sheetId + " by=" + user + " name=" + from.getName()
                + " to=" + toSheetId);
        rollup.recordChanges(user, before);
        audit.recordOnCommit("PERSON_TRANSFERRED sheet=" + toSheetId + " by=" + user + " name=" + arrived.getName()
                + " from=" + sheetId);
        rollup.recordChanges(user, otherBefore);
        // The request changes this sheet, which is kept as it commits; the other sheet is kept here.
        history.keep(toSheetId);
    }
}

