package net.officefloor.hq.app;


/**
 * Refuses every change asked for on an archived sheet: any request on a sheet other than reading it
 * (a GET, or loading the sheet) is refused before it reaches its controller, so it writes nothing.
 * As for a viewer, the bulk changes are let through and answered with every selected claim refused
 * (see {@code BulkChangeService}), and the bulk grade with no one changed (see {@code BulkGradeService}).
 */
@Component
public class ArchiveGuard implements HandlerInterceptor {

    private final SheetRepository sheets;

    public ArchiveGuard(SheetRepository sheets) {
        this.sheets = sheets;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod())) return true;
        String path = request.getRequestURI().substring(request.getContextPath().length());
        if (!path.startsWith(ViewerGuard.SHEETS)) return true;
        String rest = path.substring(ViewerGuard.SHEETS.length());
        int slash = rest.indexOf('/');
        if (slash < 0 || ViewerGuard.LET_THROUGH.contains(rest.substring(slash + 1))) return true;
        String sheetId = URLDecoder.decode(rest.substring(0, slash), StandardCharsets.UTF_8).trim();
        if (sheets.isArchived(sheetId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is archived: nothing on it can be changed.");
        }
        return true;
    }
}
package net.officefloor.hq.app;


/**
 * Refuses every change a viewer of a sheet asks for: any request on a sheet other than reading it
 * (a GET, or loading the sheet) is refused before it reaches its controller, so it writes nothing.
 * The bulk changes are let through: a viewer's bulk change is answered with every selected claim
 * refused (see {@code BulkChangeService}), a viewer's bulk grade with no one changed (see
 * {@code BulkGradeService}), and a viewer's bulk retire with no one retired (see {@code BulkRetireService}).
 */
@Component
public class ViewerGuard implements HandlerInterceptor {

    /** The path of a sheet's requests; the sheet id is the segment after it. */
    public static final String SHEETS = "/api/sheets/";

    static final Set<String> LET_THROUGH = Set.of("load", "claims/open", "claims/settle", "claims/reassign", "people/grade",
            "people/retire");

    private final SettingService settings;

    public ViewerGuard(SettingService settings) {
        this.settings = settings;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod())) return true;
        String path = request.getRequestURI().substring(request.getContextPath().length());
        String header = request.getHeader(SignedInUser.HEADER);
        if (!path.startsWith(SHEETS) || header == null || header.isBlank()) return true;
        String rest = path.substring(SHEETS.length());
        int slash = rest.indexOf('/');
        if (slash < 0 || LET_THROUGH.contains(rest.substring(slash + 1))) return true;
        String sheetId = URLDecoder.decode(rest.substring(0, slash), StandardCharsets.UTF_8).trim();
        if (settings.roleOf(sheetId, SignedInUser.name(header)) == Role.VIEWER) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "A viewer cannot change anything.");
        }
        return true;
    }
}
package net.officefloor.hq.app.asof;


/**
 * Serves a read from a screen set to an as-of date from the sheet as it stood then: the read runs
 * in one transaction that first puts the sheet back to what {@link SheetHistory} kept for that date
 * (with the as-of date as its today) and is always rolled back, so the store and the audit file are
 * left as they were. Every other request on a sheet is marked as a change of it, so each of its
 * commits is kept in the sheet's history.
 */
@Component
public class AsOfFilter extends OncePerRequestFilter {

    private final SheetHistory history;
    private final TransactionTemplate transactions;

    public AsOfFilter(SheetHistory history, PlatformTransactionManager transactionManager) {
        this.history = history;
        this.transactions = new TransactionTemplate(transactionManager);
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        Optional<String> sheet = AsOf.sheetOf(request);
        if (sheet.isEmpty()) {
            chain.doFilter(request, response);
            return;
        }
        Optional<LocalDate> asOf;
        try {
            asOf = AsOf.of(request);
        } catch (ResponseStatusException e) {
            response.sendError(e.getStatusCode().value(), e.getReason());
            return;
        }
        if (asOf.isPresent() && AsOf.reads(request)) {
            readAsOf(sheet.get(), asOf.get(), request, response, chain);
        } else if (asOf.isEmpty() && !AsOf.reads(request)) {
            history.changing(sheet.get(), () -> chain.doFilter(request, response));
        } else {
            chain.doFilter(request, response);
        }
    }

    private void readAsOf(String sheet, LocalDate asOf, HttpServletRequest request, HttpServletResponse response,
            FilterChain chain) throws ServletException, IOException {
        try {
            transactions.executeWithoutResult((status) -> {
                status.setRollbackOnly();
                history.restoreWithParents(sheet, asOf);
                try {
                    chain.doFilter(request, response);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                } catch (ServletException e) {
                    throw new WrappedServletException(e);
                }
            });
        } catch (UncheckedIOException e) {
            throw e.getCause();
        } catch (WrappedServletException e) {
            throw (ServletException) e.getCause();
        }
    }

    private static final class WrappedServletException extends RuntimeException {
        WrappedServletException(ServletException cause) {
            super(cause);
        }
    }
}

